+// Picks the response language from a request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+function headerValue(headers, name) {
+  for (const [k, v] of Object.entries(headers ?? {})) {
+    if (k.toLowerCase() === name) return Array.isArray(v) ? v.join(",") : v;
+  }
+  return undefined;
+}
+
+/** The supported language the client prefers (by q-value, ignoring region tags), or `fallback`. */
+export function requestLanguage(headers, fallback) {
+  const raw = headerValue(headers, "accept-language");
+  if (typeof raw !== "string") return fallback;
+  let best = null;
+  for (const part of raw.split(",")) {
+    const [range, ...attrs] = part.split(";").map((s) => s.trim());
+    const tag = range.toLowerCase();
+    if (!tag) continue;
+    let q = 1;
+    const qAttr = attrs.find((a) => /^q\s*=/i.test(a));
+    if (qAttr !== undefined) {
+      const value = qAttr.slice(qAttr.indexOf("=") + 1).trim();
+      if (!/^(0(\.\d{0,3})?|1(\.0{0,3})?)$/.test(value)) continue;
+      q = Number(value);
+    }
+    if (q === 0) continue;
+    const lang = tag === "*" ? fallback : tag.split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    if (!best || q > best.q) best = { lang, q };
+  }
+  return best ? best.lang : fallback;
+}
